import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: playfairFamily } = loadPlayfair();
const { fontFamily: interFamily } = loadInter();



export type StaggeredListProps = Record<string, any>;

const StaggeredList: React.FC<StaggeredListProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 6,
  backgroundImage = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/9af7f045564f4eef82b8b55f52c7e716.jpg",
  overlayOpacity = 0.65,
  listTitle = "Llueva Natural Process",
  listItems = [
    "Source Selection",
    "Filtration Process",
    "Mineral Enrichment",
    "Quality Testing",
    "Sustainable Bottling",
  ],
  themeColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Responsive scaling factor based on the smaller dimension (typically width in 9:16)
  const s = Math.min(width, height);

  // Background color logic
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Background Image Animation
  const bgScale = interpolate(frame, [0, fps * durationInSeconds], [1, 1.15], {
    extrapolateRight: "clamp",
  });

  // Title Animation
  const titleProgress = spring({
    frame: frame - 5, // Start slightly after scene begins
    fps,
    config: { damping: 16, stiffness: 100 },
  });
  // Proportionally scale the Y translation for 9:16
  const titleY = interpolate(titleProgress, [0, 1], [s * 0.1, 0]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        overflow: "hidden",
        transition: "none",
      }}
    >
      {/* Background Image */}
      <AbsoluteFill style={{ transition: "none" }}>
        <Img
          src={backgroundImage}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "cover",
            transform: `scale(${bgScale})`,
            transition: "none",
          }}
        />
      </AbsoluteFill>

      {/* Dark Overlay for Readability */}
      <AbsoluteFill
        style={{
          backgroundColor: `rgba(0,0,0,${overlayOpacity})`,
          transition: "none",
        }}
      />

      {/* Content Container - Optimized for 9:16 Vertical Stack */}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          padding: `${height * 0.15}px ${width * 0.08}px ${height * 0.1}px`, // Safe zones applied
          transition: "none",
        }}
      >
        {/* Title Area */}
        <div
          style={{
            display: "flex",
            justifyContent: "flex-start",
            alignItems: "center",
            marginBottom: height * 0.06, // Spacing between title and list
            transition: "none",
          }}
        >
          <h1
            style={{
              fontSize: s * 0.1, // Proportionally larger for 9:16
              color: themeColor,
              fontFamily: playfairFamily,
              fontWeight: 700,
              margin: 0,
              lineHeight: 1.1,
              opacity: titleProgress,
              transform: `translateY(${titleY}px)`,
              textShadow: `0 ${s * 0.004}px ${s * 0.012}px rgba(0,0,0,0.5)`,
              maxWidth: width * 0.85,
              transition: "none",
            }}
          >
            {listTitle}
          </h1>
        </div>

        {/* 5-Step List Area */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            gap: height * 0.035, // Responsive vertical spacing
            transition: "none",
          }}
        >
          {listItems.map((item, index) => {
            const itemDelay = 15 + index * 8; // Staggered by 8 frames each
            const itemProgress = spring({
              frame: frame - itemDelay,
              fps,
              config: { damping: 14, stiffness: 120 },
            });
            const itemX = interpolate(itemProgress, [0, 1], [s * 0.1, 0]);

            return (
              <div
                key={index}
                style={{
                  display: "flex",
                  alignItems: "center",
                  gap: width * 0.05, // Responsive horizontal spacing
                  opacity: itemProgress,
                  transform: `translateX(${itemX}px)`,
                  transition: "none",
                }}
              >
                {/* Step Number Circle */}
                <div
                  style={{
                    width: s * 0.09,
                    height: s * 0.09,
                    borderRadius: s * 0.045,
                    backgroundColor: themeColor,
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    fontSize: s * 0.04, // Scaled up font
                    fontWeight: 700,
                    color: "#000000",
                    fontFamily: interFamily,
                    boxShadow: `0 ${s * 0.004}px ${s * 0.015}px rgba(0,0,0,0.3)`,
                    transition: "none",
                    flexShrink: 0,
                  }}
                >
                  {index + 1}
                </div>

                {/* Step Text */}
                <div
                  style={{
                    fontSize: s * 0.05, // Scaled up text
                    color: "#ffffff",
                    fontFamily: interFamily,
                    fontWeight: 500,
                    textShadow: `0 ${s * 0.002}px ${s * 0.008}px rgba(0,0,0,0.6)`,
                    transition: "none",
                  }}
                >
                  {item}
                </div>
              </div>
            );
          })}
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default StaggeredList;